mapper.select:
select

from MST_EXCHARGE_QUOTE

	STATUS != 'D'

		AND EXCHARGE_CODE like concat(concat('%', #{exchargeCode,jdbcType=VARCHAR}),'%')


		 and STR_TO_DATE(TRADE_DATE,'%Y-%m-%d') >= #{tradeDateBegin} 


		 and STR_TO_DATE(TRADE_DATE,'%Y-%m-%d') <= #{tradeDateEnd} 


		and STR_TO_DATE(TRADE_DATE,'%Y-%m-%d') = #{tradeDate}


		and DATASOURCE_TYPE = #{datasourceType}


		and STATUS = #{status}


order by exchargeCode,tradeDate

mapper.update:
update MST_EXCHARGE_QUOTE
set STATUS=#{status}
where EXCHARGE_CODE = #{exchargeCode}
  AND TRADE_DATE = #{tradeDate}
  AND DATASOURCE_TYPE = #{datasourceType}

